  name = "renegade_loyalty&",
  mode_skill = true,
}

Fk:loadTranslationTable{
  ["renegade_loyalty&"] = "侍奉明主",
  [":renegade_loyalty&"] = "场上人数＞4且有主忠死亡时，你可以变为忠臣（不暴露身份）。（出牌阶段或每个回合结束时结算）" ..
      "
操作提示：需预亮以发动；出牌阶段空闲时从不预亮点为预亮需等待至下个空闲时发动",

  ["#renegade_loyalty&"] = "侍奉明主：是否变为忠臣？",
  ["#RenegadeChooseLoyalty"] = "内奸选择侍奉明主",
}

---@type TrigSkelSpec
local spec = {
  can_trigger = function (self, event, target, player, data)
    if not player:hasSkill(loyalty.name) or player.role ~= "renegade" or not (event == fk.TurnEnd or player == target) then return end
    local room = player.room
    return #room.alive_players > 4 and table.find(room.players, function(p) return p.dead and (p.role == "loyalist" or p.role == "lord") end)
  end,
  on_cost = function (self, event, target, player, data)
    return player.room:askToSkillInvoke(player, {
      skill_name = loyalty.name, prompt = "#renegade_loyalty&",
    })
  end,
  on_use = function (self, event, target, player, data)
    local room = player.room
    room:doSuperLightBox(nil, {
      text = "#RenegadeChooseLoyalty",
      bgColor = "transparent",
      contentAreaColor = "gray",
      contentAreaSize = 0.3,
    })
    room:changeRole(player, "loyalist")
  end,
}

