  FkTest.runInRoom(function()
    room:obtainCard(comp2, 1)
    room:useCard {
      from = me,
      tos = { comp2 },
      card = snatch,
    }
  end)
  lu.assertEquals(me.player_cards[Player.Hand], { 1 })
end)

return skill

